import json

# Test input (6x6)
input_test = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

def rot90_cw(matrix):
    n = len(matrix)
    return [[matrix[n-1-j][i] for j in range(n)] for i in range(n)]

def rot180(matrix):
    return rot90_cw(rot90_cw(matrix))

def rot270_cw(matrix):
    return rot90_cw(rot90_cw(rot90_cw(matrix)))

r0 = input_test
r90 = rot90_cw(input_test)
r180 = rot180(input_test)
r270 = rot270_cw(input_test)

n = len(input_test)
# Build output: TL=rot0, TR=rot90_cw, BL=rot270_cw, BR=rot180
output = [[0]*(2*n) for _ in range(2*n)]

# TL (top-left) = rot0
for i in range(n):
    for j in range(n):
        output[i][j] = r0[i][j]

# TR (top-right) = rot90_cw
for i in range(n):
    for j in range(n):
        output[i][n+j] = r90[i][j]

# BL (bottom-left) = rot270_cw
for i in range(n):
    for j in range(n):
        output[n+i][j] = r270[i][j]

# BR (bottom-right) = rot180
for i in range(n):
    for j in range(n):
        output[n+i][n+j] = r180[i][j]

print("Output grid (12x12):")
for row in output:
    print(row)

# Verify it's correct by printing as json
print("\nJSON output:")
print(json.dumps(output))
